with wanted(name,product_id) as (values ('Plain Cheesecake','cheesecake'),('Plain Cheese Cake','cheesecake'),('Plain Cream Cheese Cake','cheesecake'),('Pistachio Cheesecake','sheet-9fad2225f6'),('Pistachio Cheese Cake','sheet-9fad2225f6'),('Earl Grey Cheesecake','sheet-e7cab97855'),('Earl Grey Cheese Cake','sheet-e7cab97855')), changed as (update public.kream_clover_items i set product_id=w.product_id,stock_per_sale=0.1,enabled=true,updated_at=clock_timestamp() from wanted w join public.kream_catalog p on p.id=w.product_id and p.active and p.order_unit='Tray' where lower(trim(i.name))=lower(w.name) and (i.product_id is null or i.product_id=w.product_id) returning i.store_id,i.name,i.stock_per_sale) select * from changed order by store_id,name;
